def match(orders):
    trades = []
    buy_book = []  # [(price, arrival_time, id, qty)]
    sell_book = []  # [(price, arrival_time, id, qty)]
    order_map = {}  # {id: (side, original_qty, filled_qty, order_index)}
    arrival_counter = 0

    for order in orders:
        if order[0] == 'cancel':
            _, id_ = order
            if id_ in order_map:
                side, original_qty, filled_qty, order_index = order_map[id_]
                if filled_qty < original_qty:  # Only cancel if not fully filled
                    if side == 'buy':
                        buy_book[:] = [(p, t, oid, q) for p, t, oid, q in buy_book if oid != id_]
                    else:
                        sell_book[:] = [(p, t, oid, q) for p, t, oid, q in sell_book if oid != id_]
                    del order_map[id_]

        else:
            order_type = order[0]
            id_ = order[1]
            side = order[2]
            qty = order[3] if order_type == 'market' else order[4]
            price = order[3] if order_type != 'market' else None

            order_map[id_] = [side, qty, 0, arrival_counter]
            arrival_counter += 1

            remaining_qty = qty

            # Match incoming order
            if side == 'buy':
                # Match against sell_book, lowest price first, then earliest
                sell_book.sort(key=lambda x: (x[0], x[1]))

                matched_indices = []
                for i, (sell_price, sell_arrival, sell_id, sell_qty) in enumerate(sell_book):
                    if remaining_qty == 0:
                        break
                    if order_type == 'market' or price >= sell_price:
                        trade_qty = min(remaining_qty, sell_qty)
                        trades.append([id_, sell_id, sell_price, trade_qty])

                        remaining_qty -= trade_qty
                        order_map[id_][2] += trade_qty

                        sell_remaining = sell_qty - trade_qty
                        order_map[sell_id][2] += trade_qty

                        if sell_remaining > 0:
                            sell_book[i] = (sell_price, sell_arrival, sell_id, sell_remaining)
                        else:
                            matched_indices.append(i)

                # Remove fully matched sell orders
                for i in reversed(matched_indices):
                    sell_book.pop(i)

            else:  # side == 'sell'
                # Match against buy_book, highest price first, then earliest
                buy_book.sort(key=lambda x: (-x[0], x[1]))

                matched_indices = []
                for i, (buy_price, buy_arrival, buy_id, buy_qty) in enumerate(buy_book):
                    if remaining_qty == 0:
                        break
                    if order_type == 'market' or price <= buy_price:
                        trade_qty = min(remaining_qty, buy_qty)
                        trades.append([buy_id, id_, buy_price, trade_qty])

                        remaining_qty -= trade_qty
                        order_map[id_][2] += trade_qty

                        buy_remaining = buy_qty - trade_qty
                        order_map[buy_id][2] += trade_qty

                        if buy_remaining > 0:
                            buy_book[i] = (buy_price, buy_arrival, buy_id, buy_remaining)
                        else:
                            matched_indices.append(i)

                # Remove fully matched buy orders
                for i in reversed(matched_indices):
                    buy_book.pop(i)

            # Add remaining quantity to book if limit order
            if order_type == 'limit' and remaining_qty > 0:
                if side == 'buy':
                    buy_book.append((price, order_map[id_][3], id_, remaining_qty))
                else:
                    sell_book.append((price, order_map[id_][3], id_, remaining_qty))

    return trades

